const DIVISION_RENAMES = {
  "Electrical": "26 - Electrical",
};
function applyDivisionRenames(list) {
  return list.map((c) => (DIVISION_RENAMES[c.division] ? { ...c, division: DIVISION_RENAMES[c.division] } : c));
}

const DIVISION_PALETTE = ["#E5484D", "#4C7EF2", "#34A65F", "#C1553A", "#8B6BAE", "#3E8E7E", "#B8863E", "#5C6470"];
function colorForDivision(name) {
  let hash = 0;
  for (let i = 0; i < name.length; i++) hash = (hash * 31 + name.charCodeAt(i)) % 999983;
  return DIVISION_PALETTE[hash % DIVISION_PALETTE.length];
}

const pad = (n) => String(n).padStart(2, "0");
const toKey = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const isSameDay = (a, b) => toKey(a) === toKey(b);

// "10 - Toilet & Bath Accessories" splits into division "10" and scope "Toilet & Bath Accessories".
// A division string with no leading "N - " (e.g. "Electrical") becomes its own top-level group with companies listed directly.
function parseDivision(divStr) {
  const cleaned = (divStr || "General").trim().replace(/^division\s+/i, "").trim();
  const m = /^(\d+)\s*-\s*(.+)$/.exec(cleaned);
  if (m) return { num: m[1], scope: m[2].trim() };
  return { num: cleaned || "General", scope: null };
}

function buildDivisionTree(companies) {
  const tree = {};
  companies.forEach((c) => {
    const { num, scope } = parseDivision(c.division);
    if (!tree[num]) tree[num] = { scopes: {}, direct: [] };
    if (scope) {
      if (!tree[num].scopes[scope]) tree[num].scopes[scope] = [];
      tree[num].scopes[scope].push(c);
    } else {
      tree[num].direct.push(c);
    }
  });
  return tree;
}

function downloadDataUri(dataUri, filename) {
  const a = document.createElement("a");
  a.href = dataUri;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
}

function genId() {
  return "u-" + Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
}

function mapStatusText(raw) {
  const s = (raw || "").toString().trim().toLowerCase();
  if (s.includes("confirm")) return "confirmed";
  if (s.includes("complete") || s.includes("deliver")) return "complete";
  return "tentative"; // covers "pending", "tentative", blank, or anything unrecognized
}

function mapEquipmentText(raw) {
  const s = (raw || "").toString().trim().toLowerCase().replace(/\s+/g, "");
  if (!s) return null;
  if (s === "1" || s.includes("crane1")) return "crane1";
  if (s === "2" || s.includes("crane2")) return "crane2";
  if (s.includes("buckhoist") || s.includes("bh") || s.includes("hoist")) return "buckhoist";
  return null;
}

// Accepts a JS Date (from SheetJS cellDates:true), an Excel serial number, or a text date/time.
function excelValueToDate(val, XLSXRef) {
  if (val instanceof Date && !isNaN(val.getTime())) return val;
  if (typeof val === "number") {
    try {
      const p = XLSXRef.SSF.parse_date_code(val);
      if (p) return new Date(p.y, (p.m || 1) - 1, p.d || 1, p.H || 0, p.M || 0, Math.floor(p.S || 0));
    } catch (e) {
      // fall through
    }
  }
  if (typeof val === "string" && val.trim()) {
    const d = new Date(val);
    if (!isNaN(d.getTime())) return d;
  }
  return null;
}

function excelDateToKey(val, XLSXRef) {
  const d = excelValueToDate(val, XLSXRef);
  return d ? toKey(d) : null;
}

// Returns hour-of-day as a decimal (e.g. 13.5 for 1:30 PM), or null if it can't be read.
function excelValueToHour(val, XLSXRef) {
  const d = excelValueToDate(val, XLSXRef);
  if (d) return d.getHours() + d.getMinutes() / 60;
  if (typeof val === "number" && val >= 0 && val < 1) return val * 24; // bare time-of-day serial
  if (typeof val === "string") {
    const m = /^(\d{1,2}):(\d{2})\s*(AM|PM|am|pm)?$/.exec(val.trim());
    if (m) {
      let h = parseInt(m[1], 10);
      const mins = parseInt(m[2], 10);
      const ap = m[3] ? m[3].toUpperCase() : null;
      if (ap === "PM" && h !== 12) h += 12;
      if (ap === "AM" && h === 12) h = 0;
      return h + mins / 60;
    }
  }
  return null;
}

function hourToTimeInputValue(h) {
  if (h == null) return "";
  const total = Math.round(h * 60);
  return `${pad(Math.floor(total / 60))}:${pad(total % 60)}`;
}

function timeInputValueToHour(str) {
  if (!str) return null;
  const [h, m] = str.split(":").map(Number);
  if (Number.isNaN(h)) return null;
  return h + (m || 0) / 60;
}

// Filenames follow "CompanyName_DeliverySchedule_MM.DD.YYYY.xlsx" — pull the company segment.
function extractCompanyNameFromFilename(filename) {
  const base = filename.replace(/\.[^.]+$/, "");
  const parts = base.split("_");
  return parts[0] ? parts[0].trim().replace(/[-]+/g, " ").trim() : "";
}

function guessCompanyFromName(companies, guess) {
  if (!guess) return null;
  const norm = (s) => s.toLowerCase().replace(/[^a-z0-9]/g, "");
  const g = norm(guess);
  if (!g) return null;
  let match = companies.find((c) => norm(c.name) === g);
  if (match) return match;
  match = companies.find((c) => norm(c.name).includes(g) || g.includes(norm(c.name)));
  return match || null;
}

function initialsFor(name) {
  const parts = (name || "").trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

// Produces a 3-letter acronym for a company name, e.g. "AWM Group" -> "AWM", "KD Construction" -> "KDC".
function companyAcronym(name) {
  const rawWords = (name || "").trim().split(/\s+/).filter(Boolean);
  const cleanWords = rawWords.map((w) => w.replace(/[^A-Za-z0-9]/g, "")).filter(Boolean);
  if (cleanWords.length === 0) return "???";

  // Prefer a word that already looks like an acronym (short, all caps).
  const capsIdx = cleanWords.findIndex((w) => {
    const letters = w.replace(/[0-9]/g, "");
    return letters.length >= 2 && letters.length <= 4 && letters === letters.toUpperCase();
  });
  if (capsIdx !== -1) {
    let letters = cleanWords[capsIdx];
    if (letters.length >= 3) return letters.slice(0, 3).toUpperCase();
    const donor = cleanWords[capsIdx + 1] || cleanWords[capsIdx - 1] || "";
    letters = (letters + donor).slice(0, 3);
    return (letters + "XXX").slice(0, 3).toUpperCase();
  }

  if (cleanWords.length >= 3) return (cleanWords[0][0] + cleanWords[1][0] + cleanWords[2][0]).toUpperCase();
  if (cleanWords.length === 2) {
    const [a, b] = cleanWords;
    const third = b.length > 1 ? b[1] : a.length > 1 ? a[1] : "X";
    return (a[0] + b[0] + third).toUpperCase();
  }
  const w = cleanWords[0];
  return (w.length >= 3 ? w : w + "XXX").slice(0, 3).toUpperCase();
}

function shiftDateKey(key, dir) {
  const [y, m, d] = key.split("-").map(Number);
  const date = new Date(y, m - 1, d);
  date.setDate(date.getDate() + dir);
  if (date.getDay() === 0) date.setDate(date.getDate() + dir); // skip Sunday
  return toKey(date);
}

function formatHour(h) {
  const totalMin = Math.round(h * 60);
  let hh = Math.floor(totalMin / 60);
  const mm = totalMin % 60;
  const period = hh >= 12 ? "PM" : "AM";
  let hh12 = hh % 12;
  if (hh12 === 0) hh12 = 12;
  return `${hh12}:${pad(mm)} ${period}`;
}

function buildMonthGrid(year, month) {
  const firstOfMonth = new Date(year, month, 1);
  const firstWeekday = firstOfMonth.getDay(); // 0 = Sun ... 6 = Sat
  const offsetToMonday = firstWeekday === 0 ? 6 : firstWeekday - 1;
  const gridStart = new Date(year, month, 1 - offsetToMonday);
  const cells = [];
  for (let row = 0; row < 6; row++) {
    for (let col = 0; col < 6; col++) {
      const d = new Date(gridStart);
      d.setDate(gridStart.getDate() + row * 7 + col); // col 0-5 = Mon-Sat, Sunday (col 6) is skipped
      cells.push(d);
    }
  }
  // Drop a trailing row if it's entirely outside the target month
  const lastRowStart = cells[30];
  if (lastRowStart.getMonth() !== month || lastRowStart.getFullYear() !== year) {
    return cells.slice(0, 30);
  }
  return cells;
}

let uid = 1;
const nextId = () => `ev-${Date.now()}-${uid++}`;

const TIME_OPTIONS = (() => {
  const opts = [];
  for (let h = START_HOUR; h <= END_HOUR; h += 0.5) opts.push({ value: h, label: formatHour(h) });
  return opts;
})();

function blockedRangesForDate(dateKey, restrictions) {
  const list = restrictions.filter((r) => r.dateKey === dateKey);
  if (list.some((r) => r.allDay)) return [{ startHour: START_HOUR, duration: END_HOUR - START_HOUR }];
  return list.map((r) => ({ startHour: r.startHour, duration: r.finishHour - r.startHour }));
}

function rangeIsRestricted(dateKey, startHour, duration, restrictions) {
  return blockedRangesForDate(dateKey, restrictions).some(
    (b) => startHour < b.startHour + b.duration && b.startHour < startHour + duration
  );
}

function findAvailableStart(dateKey, desiredHour, duration, allEvents, restrictions) {
  const dayItems = allEvents.filter((e) => e.dateKey === dateKey).map((e) => ({ startHour: e.startHour, duration: e.duration }));
  const blocked = blockedRangesForDate(dateKey, restrictions || []);
  const busy = [...dayItems, ...blocked].sort((a, b) => a.startHour - b.startHour);
  const maxStart = END_HOUR - duration;
  let start = Math.max(desiredHour, START_HOUR);
  while (start <= maxStart) {
    const conflict = busy.find((e) => start < e.startHour + e.duration && e.startHour < start + duration);
    if (!conflict) return start;
    start = conflict.startHour + conflict.duration;
  }
  // No open slot found in the window; place at the latest possible start as a fallback
  return Math.max(START_HOUR, Math.min(desiredHour, maxStart));
}

