  // --- drag-to-move / drag-to-resize inside day view ---
  useEffect(() => {
    if (!dragState) return;
    function onMove(e) {
      const deltaY = e.clientY - dragState.startY;
      const deltaHours = deltaY / HOUR_HEIGHT;
      setEvents((prev) =>
        prev.map((ev) => {
          if (ev.id !== dragState.id) return ev;
          if (dragState.mode === "move") {
            let newStart = Math.round((dragState.startHour + deltaHours) * 4) / 4;
            newStart = Math.min(Math.max(newStart, START_HOUR), END_HOUR - ev.duration);
            if (ev.type !== "blockout" && rangeIsRestricted(ev.dateKey, newStart, ev.duration, restrictions)) return ev;
            const updated = { ...ev, startHour: newStart };
            if (ev.type === "delivery" && timelineRef.current) {
              const rect = timelineRef.current.getBoundingClientRect();
              if (rect.width > 0) {
                const relX = e.clientX - rect.left;
                const colIndex = Math.min(Math.max(Math.floor((relX / rect.width) * EQUIPMENT_OPTIONS.length), 0), EQUIPMENT_OPTIONS.length - 1);
                updated.equipment = EQUIPMENT_OPTIONS[colIndex];
              }
            }
            return updated;
          } else {
            let newDuration = Math.round((dragState.startDuration + deltaHours) * 4) / 4;
            newDuration = Math.min(Math.max(newDuration, 0.5), END_HOUR - ev.startHour);
            if (ev.type !== "blockout" && rangeIsRestricted(ev.dateKey, ev.startHour, newDuration, restrictions)) return ev;
            return { ...ev, duration: newDuration };
          }
        })
      );
    }
    function onUp() {
      setDragState(null);
    }
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
    return () => {
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
    };
  }, [dragState, restrictions]);

