  function runExport(weeks) {
    const start = new Date();
    const rows = [];
    for (let i = 0; i < weeks * 7; i++) {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      if (d.getDay() === 0) continue; // skip Sundays, no deliveries scheduled
      const key = toKey(d);
      const dayDeliveries = events
        .filter((e) => e.dateKey === key && e.type === "delivery")
        .sort((a, b) => a.startHour - b.startHour);
      const dayBlockouts = events
        .filter((e) => e.dateKey === key && e.type === "blockout")
        .sort((a, b) => a.startHour - b.startHour);
      const dayRestrictions = restrictions.filter((r) => r.dateKey === key);
      rows.push({ dateObj: d, dateKey: key, deliveries: dayDeliveries, blockouts: dayBlockouts, restrictions: dayRestrictions });
    }
    setExportReport({ kind: "lookahead", weeks, generatedAt: new Date(), rows });
    setExportMenu(null);
  }

  function buildCraneSections(days) {
    return EQUIPMENT_OPTIONS.map((eqKey) => ({
      equipment: eqKey,
      name: EQUIPMENT_NAMES[eqKey],
      days: days.map((day) => ({
        ...day,
        deliveries: events
          .filter((e) => e.dateKey === day.dateKey && e.type === "delivery" && e.equipment === eqKey)
          .sort((a, b) => a.startHour - b.startHour),
        restrictions: restrictions.filter((r) => r.dateKey === day.dateKey),
      })),
    }));
  }

