  function nextWorkingDateKey(dateObj) {
    const d = new Date(dateObj);
    // eslint-disable-next-line no-constant-condition
    while (true) {
      if (d.getDay() !== 0 && !isNoWorkDay(toKey(d))) return toKey(d);
      d.setDate(d.getDate() + 1);
    }
  }

  function handleImportFile(e) {
    const file = e.target.files && e.target.files[0];
    e.target.value = ""; // allow re-choosing the same file later
    if (!file) return;
    setImportError("");
    setImportGuessedName("");

    const guess = extractCompanyNameFromFilename(file.name);
    const matched = guessCompanyFromName(companies, guess);
    if (guess) setImportGuessedName(guess);
    if (matched) setImportCompanyId(matched.id);

    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const data = new Uint8Array(evt.target.result);
        const wb = XLSX.read(data, { type: "array", cellDates: true });
        const sheet = wb.Sheets[wb.SheetNames[0]];
        const rawRows = XLSX.utils.sheet_to_json(sheet, { defval: "" });
        const findKey = (obj, target) => Object.keys(obj).find((k) => k.trim().toLowerCase() === target);
        const parsed = rawRows
          .map((r) => {
            const descKey = findKey(r, "description");
            const statusKey = findKey(r, "status");
            const equipKey = findKey(r, "planned equipment");
            const dateKeyCol = findKey(r, "date");
            const startKey = findKey(r, "start time");
            const endKey = findKey(r, "end time");
            return {
              description: descKey ? String(r[descKey]).trim() : "",
              statusRaw: statusKey ? r[statusKey] : "",
              equipmentRaw: equipKey ? r[equipKey] : "",
              dateRaw: dateKeyCol ? r[dateKeyCol] : "",
              startRaw: startKey ? r[startKey] : "",
              endRaw: endKey ? r[endKey] : "",
            };
          })
          .filter((r) => r.description);

        if (parsed.length === 0) {
          setImportError('No rows found. Make sure the file has "Description", "Status", and "Planned Equipment" columns.');
          return;
        }

        let cursor = new Date();
        cursor.setDate(cursor.getDate() + 1); // fallback start date for rows with no Date column
        const rows = parsed.map((r) => {
          const explicitDateKey = r.dateRaw !== "" ? excelDateToKey(r.dateRaw, XLSX) : null;
          let dateKey = explicitDateKey;
          if (!dateKey) {
            dateKey = nextWorkingDateKey(cursor);
            const [yy, mm, dd] = dateKey.split("-").map(Number);
            cursor = new Date(yy, mm - 1, dd);
            cursor.setDate(cursor.getDate() + 1);
          }

          const startHourRaw = r.startRaw !== "" ? excelValueToHour(r.startRaw, XLSX) : null;
          const endHourRaw = r.endRaw !== "" ? excelValueToHour(r.endRaw, XLSX) : null;
          let startHour = startHourRaw != null ? Math.min(Math.max(startHourRaw, START_HOUR), END_HOUR - 0.5) : null;
          let duration = 1;
          if (startHour != null && endHourRaw != null && endHourRaw > startHourRaw) {
            duration = Math.min(Math.max(endHourRaw - startHourRaw, 0.5), END_HOUR - startHour);
          }

          return {
            id: nextId(),
            description: r.description,
            status: mapStatusText(r.statusRaw),
            equipment: mapEquipmentText(r.equipmentRaw),
            dateKey,
            startHour,
            duration,
          };
        });
        setImportRows(rows);
        setImportStep("review");
      } catch (err) {
        setImportError("Could not read that file. Please upload a valid .xlsx file with Description, Status, and Planned Equipment columns.");
      }
    };
    reader.readAsArrayBuffer(file);
  }

