  function handleCellDrop(e, date) {
    e.preventDefault();
    const companyId = e.dataTransfer.getData("text/plain");
    if (!companyId) return;
    const key = toKey(date);
    if (isNoWorkDay(key)) {
      setDragOverKey(null);
      return;
    }
    const startHour = findAvailableStart(key, 9, 1, events, restrictions);
    const dropComp = companyById(companyId);
    setSelectedDate(key);
    setDragOverKey(null);
    setPendingStatus("tentative");
    setPendingEquipment(null);
    setPendingName(dropComp ? dropComp.name : "");
    setPendingCritical(false);
    setPendingDrop({ companyId, dateKey: key, startHour, duration: 1 });
  }

  function handleTimelineDrop(e) {
    e.preventDefault();
    const companyId = e.dataTransfer.getData("text/plain");
    if (!companyId || !timelineRef.current) return;
    if (isNoWorkDay(selectedDate)) {
      setDayDragOver(false);
      return;
    }
    const rect = timelineRef.current.getBoundingClientRect();
    const offsetY = e.clientY - rect.top;
    let hour = START_HOUR + offsetY / HOUR_HEIGHT;
    hour = Math.round(hour * 4) / 4;
    hour = Math.min(Math.max(hour, START_HOUR), END_HOUR - 1);
    const startHour = findAvailableStart(selectedDate, hour, 1, events, restrictions);
    const offsetX = e.clientX - rect.left;
    const colIndex = Math.min(Math.max(Math.floor((offsetX / rect.width) * EQUIPMENT_OPTIONS.length), 0), EQUIPMENT_OPTIONS.length - 1);
    const dropComp = companyById(companyId);
    setDayDragOver(false);
    setPendingStatus("tentative");
    setPendingEquipment(EQUIPMENT_OPTIONS[colIndex]);
    setPendingName(dropComp ? dropComp.name : "");
    setPendingCritical(false);
    setPendingDrop({ companyId, dateKey: selectedDate, startHour, duration: 1 });
  }

